export default function TechIcon({ name, size = 22 }: Props) {
  const icon = icons[name] ?? <FallbackIcon />;
  return (
    <span
      style={{
        width: size,
        height: size,
        display: "inline-flex",
        flexShrink: 0,
      }}
      aria-label={name}
      role="img"
    >
      {icon}
    </span>
  );
}
